import axiosConfig from "../axiosConfig"
export const apiUserRegister = (data) => new Promise(async(resolve, reject) => {
    try {
        const response = await axiosConfig({
            method: 'posy',
            url: '/api/user/register',
            data: data
        })
        resolve(response)
    } catch (error) {
        reject(error)
    }
})

export const apiUserLogin = (data) => new Promise(async(resolve, reject) => {
    try {
        const response = await axiosConfig({
            method: 'post',
            url: '/api/user/login',
            data: data
        })
        resolve(response)
    } catch (error) {
        reject(error)
    }
})
